import '../../models/daily_nutrition.dart';
import '../../models/recovery_summary.dart';
import '../../models/workout_recommendation.dart';

/// Notification generated by AI Coach
class CoachSmartNotification {
  final String id;
  final String title;
  final String body;
  final String category; // 'workout', 'nutrition', 'recovery', 'achievement'
  final DateTime timestamp;
  final String? route;

  const CoachSmartNotification({
    required this.id,
    required this.title,
    required this.body,
    required this.category,
    required this.timestamp,
    this.route,
  });
}

/// Intelligent AI Coach Notification Service that evaluates daily state
/// and generates non-spam, context-aware coaching reminders (maximum 3 per day).
class CoachNotificationService {
  static CoachNotificationService? _instance;
  static CoachNotificationService get instance =>
      _instance ??= CoachNotificationService();

  /// Evaluates recovery, training split, and nutrition delta to generate prioritized smart notifications.
  List<CoachSmartNotification> generateDailyNotifications({
    required RecoverySummary recovery,
    required WorkoutRecommendation workout,
    required DailyNutrition? todayNutrition,
    int maxNotificationsPerDay = 3,
  }) {
    final notifications = <CoachSmartNotification>[];
    final now = DateTime.now();

    // 1. Recovery Alert (High Priority if fatigued)
    final sleep = recovery.sleepHours;
    if (recovery.isMeasured &&
        (recovery.score < 50 || (sleep != null && sleep > 0 && sleep < 6.0))) {
      notifications.add(
        CoachSmartNotification(
          id: 'notif_rec_${now.millisecondsSinceEpoch}',
          title: 'Recovery Alert 💤',
          body:
              '${sleep == null ? 'Sleep not recorded' : 'Sleep was ${sleep.toStringAsFixed(1)}h'} (Readiness: ${recovery.score}%). Consider a light recovery session today.',
          category: 'recovery',
          timestamp: now,
          route: '/recovery',
        ),
      );
    }

    // 2. Workout Scheduled Reminder
    if (!workout.isRestDay && workout.title.isNotEmpty) {
      notifications.add(
        CoachSmartNotification(
          id: 'notif_wo_${now.millisecondsSinceEpoch}',
          title: 'Training Reminder 🏋️',
          body:
              'Your ${workout.title} session is scheduled today. Ready to crush it?',
          category: 'workout',
          timestamp: now,
          route: '/workout',
        ),
      );
    }

    // 3. Nutrition / Protein Pacing Reminder
    if (todayNutrition != null) {
      // Null when some food has no protein value: no reminder then, since
      // the real amount still needed is unknown.
      final remainingProtein = todayNutrition.proteinRemaining(
        todayNutrition.targets.protein,
      );
      if (remainingProtein != null && remainingProtein > 30.0) {
        notifications.add(
          CoachSmartNotification(
            id: 'notif_nut_${now.millisecondsSinceEpoch}',
            title: 'Protein Goal 🥩',
            body:
                'You need ${remainingProtein.toInt()}g more protein today to hit your muscle recovery target.',
            category: 'nutrition',
            timestamp: now,
            route: '/nutrition',
          ),
        );
      }
    }

    // Cap at maxNotificationsPerDay
    return notifications.take(maxNotificationsPerDay).toList();
  }
}
